def lastNonEmptyString(s: str) -> str:
    # Count frequency of each character
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1

    # Find the maximum frequency
    max_freq = max(freq.values())

    # Build result string with characters that have max frequency
    # But we need to preserve the order of their last occurrence
    result = []
    seen = set()

    # Traverse the string from left to right
    # Only add a character if it has max frequency and hasn't been added yet
    for char in s:
        if freq[char] == max_freq and char not in seen:
            result.append(char)
            seen.add(char)

    return ''.join(result)
```

