def shortest_unique_substrings(arr):
    n = len(arr)
    # Precompute all substrings for each string, grouped by length
    all_substrings = []
    for s in arr:
        subs = set()
        for i in range(len(s)):
            for j in range(i+1, len(s)+1):
                subs.add(s[i:j])
        all_substrings.append(subs)

    result = []
    for i in range(n):
        best = None
        # Try substrings from shortest to longest
        for length in range(1, len(arr[i]) + 1):
            for start in range(len(arr[i]) - length + 1):
                sub = arr[i][start:start+length]
                # Check if this substring appears in any other string
                unique = True
                for j in range(n):
                    if i != j and sub in all_substrings[j]:
                        unique = False
                        break
                if unique:
                    if best is None or sub < best:
                        best = sub
            # If we found any substring of this length, no need to check longer ones
            if best is not None and len(best) == length:
                break
        result.append(best if best is not None else "")

    return result
