def longestCommonSuffix(wordsContainer, wordsQuery):
    class TrieNode:
        __slots__ = ('children', 'best')
        def __init__(self):
            self.children = {}
            self.best = None  # (length, index) tuple, smallest length then smallest index

    root = TrieNode()
    # Build trie on reversed words, storing best candidate at each node
    for idx, word in enumerate(wordsContainer):
        length = len(word)
        candidate = (length, idx)
        node = root
        # Update root (empty suffix)
        if node.best is None or candidate < node.best:
            node.best = candidate
        # Insert reversed word character by character
        for ch in reversed(word):
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            # Update best candidate for this suffix
            if node.best is None or candidate < node.best:
                node.best = candidate

    # Answer each query
    ans = []
    for query in wordsQuery:
        node = root
        # Traverse reversed query as far as possible
        for ch in reversed(query):
            if ch in node.children:
                node = node.children[ch]
            else:
                break
        # Retrieve index from best candidate at the deepest node reached
        ans.append(node.best[1])
    return ans
```

