def minimize_join_length(words):
    n = len(words)
    # dp[i][first_char][last_char] = minimum length of string formed from first i+1 words
    # that starts with first_char and ends with last_char
    INF = 10**9

    # Initialize with first word
    dp = {}
    first_word = words[0]
    first_char = first_word[0]
    last_char = first_word[-1]
    dp[(first_char, last_char)] = len(first_word)

    for i in range(1, n):
        new_dp = {}
        w = words[i]
        w_len = len(w)
        w_first = w[0]
        w_last = w[-1]

        for (prev_first, prev_last), prev_len in dp.items():
            # Option 1: join(prev_string, w)
            if prev_last == w_first:
                new_len1 = prev_len + w_len - 1
            else:
                new_len1 = prev_len + w_len
            key1 = (prev_first, w_last)
            if key1 not in new_dp or new_len1 < new_dp[key1]:
                new_dp[key1] = new_len1

            # Option 2: join(w, prev_string)
            if w_last == prev_first:
                new_len2 = w_len + prev_len - 1
            else:
                new_len2 = w_len + prev_len
            key2 = (w_first, prev_last)
            if key2 not in new_dp or new_len2 < new_dp[key2]:
                new_dp[key2] = new_len2

        dp = new_dp

    # Return minimum length among all possible first/last character combinations
    return min(dp.values())
