def min_anagram_length(s: str) -> int:
    n = len(s)
    for length in range(1, n + 1):
        if n % length != 0:
            continue
        freq = [0] * 26
        for i in range(length):
            freq[ord(s[i]) - ord('a')] += 1
        ok = True
        for i in range(length, n, length):
            curr_freq = [0] * 26
            for j in range(i, i + length):
                curr_freq[ord(s[j]) - ord('a')] += 1
            if curr_freq != freq:
                ok = False
                break
        if ok:
            return length
    return n
