def min_deletions(word: str, k: int) -> int:
    freq = [0] * 26
    for ch in word:
        freq[ord(ch) - 97] += 1
    max_f = max(freq)
    total_len = len(word)
    max_keep = 0
    for L in range(max_f + 1):
        keep = 0
        U = L + k
        for f in freq:
            if f >= L:
                keep += min(f, U)
        if keep > max_keep:
            max_keep = keep
    return total_len - max_keep
