MOD = 10**9 + 7

def numberOfStableArrays(zero: int, one: int, limit: int) -> int:
    max_n = max(zero, one)
    # dp[n][k] = number of ordered compositions of n into k parts,
    # each part between 1 and limit (inclusive)
    dp = [[0] * (max_n + 1) for _ in range(max_n + 1)]
    dp[0][0] = 1
    for n in range(1, max_n + 1):
        for k in range(1, n + 1):
            total = 0
            # part size t from 1 to min(limit, n)
            max_part = min(limit, n)
            for t in range(1, max_part + 1):
                total = (total + dp[n - t][k - 1]) % MOD
            dp[n][k] = total

    ans = 0
    for a in range(1, zero + 1):
        for b in range(1, one + 1):
            ways0 = dp[zero][a]
            ways1 = dp[one][b]
            if ways0 == 0 or ways1 == 0:
                continue
            if a == b:
                ans = (ans + 2 * ways0 % MOD * ways1) % MOD
            elif a == b + 1:
                ans = (ans + ways0 * ways1) % MOD
            elif b == a + 1:
                ans = (ans + ways0 * ways1) % MOD
    return ans % MOD
