import sys
from collections import deque

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    H = int(next(it))
    W = int(next(it))
    T = int(next(it))
    grid = []
    for _ in range(H):
        row = next(it)
        grid.append(row)

    # locate important cells
    start = None
    goal = None
    candies = []
    for i in range(H):
        for j,ch in enumerate(grid[i]):
            if ch == 'S':
                start = (i,j)
            elif ch == 'G':
                goal = (i,j)
            elif ch == 'o':
                candies.append((i,j))

    # combine all important points: start (0), candies (1..K), goal (K+1)
    points = [start] + candies + [goal]
    K = len(candies)
    n = len(points)  # 2 + K

    # distance matrix
    INF = 10**9
    dist = [[INF]*n for _ in range(n)]
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]

    # BFS from each important point to all cells
    for idx, (sr, sc) in enumerate(points):
        d = [[-1]*W for _ in range(H)]
        q = deque()
        d[sr][sc] = 0
        q.append((sr,sc))
        while q:
            r,c = q.popleft()
            for dr,dc in dirs:
                nr, nc = r+dr, c+dc
                if 0 <= nr < H and 0 <= nc < W and d[nr][nc] == -1 and grid[nr][nc] != '#':
                    d[nr][nc] = d[r][c] + 1
                    q.append((nr,nc))
        # fill distances to other important points
        for jdx, (tr,tc) in enumerate(points):
            if jdx == idx:
                dist[idx][jdx] = 0
            elif d[tr][tc] != -1:
                dist[idx][jdx] = d[tr][tc]
            # else stays INF

    # direct start -> goal
    if dist[0][n-1] > T:
        print(-1)
        return

    # DP over subsets of candies
    # dp[mask][last] where last is index of candy (1..K)
    # map last (candy index) to its position in points: 1 + (candy_index)
    dp = [[INF]* (K+1) for _ in range(1<<K)]
    # base: start to one candy
    for i in range(1, K+1):
        if dist[0][i] < INF:
            dp[1<<(i-1)][i] = dist[0][i]

    # iterate masks
    for mask in range(1<<K):
        for last in range(1, K+1):
            if not (mask & (1<<(last-1))):
                continue
            cur = dp[mask][last]
            if cur >= INF:
                continue
            # try to add another candy
            for nxt in range(1, K+1):
                if mask & (1<<(nxt-1)):
                    continue
                nmask = mask | (1<<(nxt-1))
                nd = cur + dist[last][nxt]
                if nd < dp[nmask][nxt]:
                    dp[nmask][nxt] = nd

    # compute answer
    best = 0
    # include case of no candies (already covered by start->goal check)
    for mask in range(1<<K):
        if mask == 0:
            continue
        for last in range(1, K+1):
            if not (mask & (1<<(last-1))):
                continue
            total = dp[mask][last] + dist[last][n-1]
            if total <= T:
                cnt = bin(mask).count('1')
                if cnt > best:
                    best = cnt
    print(best)

if __name__ == "__main__":
    solve()
