def minimumCost(source, target, original, changed, cost):
    n = 26  # number of lowercase English letters
    INF = 10**18
    # Initialize distance matrix
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    # Set direct transformation costs (keep minimum if duplicate)
    for u, v, w in zip(original, changed, cost):
        i = ord(u) - ord('a')
        j = ord(v) - ord('a')
        if w < dist[i][j]:
            dist[i][j] = w
    # Floyd-Warshall to find all-pairs shortest paths
    for k in range(n):
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == INF:
                continue
            di = dist[i]
            for j in range(n):
                nd = dik + dk[j]
                if nd < di[j]:
                    di[j] = nd
    # Compute total cost for each character position
    total = 0
    for s, t in zip(source, target):
        if s == t:
            continue
        i = ord(s) - ord('a')
        j = ord(t) - ord('a')
        if dist[i][j] == INF:
            return -1
        total += dist[i][j]
