def shortestBeautifulSubstring(s: str, k: int) -> str:
    """
    Returns the lexicographically smallest beautiful substring of s with length
    equal to the shortest possible length. A beautiful substring contains exactly k '1's.
    If no such substring exists, returns an empty string.
    """
    n = len(s)
    # prefix sum of ones: prefix[i] = number of ones in s[0:i]
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + (1 if s[i] == '1' else 0)

    min_len = float('inf')
    candidates = []

    # enumerate all substrings
    for i in range(n):
        for j in range(i, n):
            if prefix[j + 1] - prefix[i] == k:
                length = j - i + 1
                if length < min_len:
                    min_len = length
                    candidates = [s[i:j + 1]]
                elif length == min_len:
                    candidates.append(s[i:j + 1])

    if not candidates:
        return ""
    # lexicographically smallest among substrings of minimal length
    return min(candidates)
