    tile_areas = [a * b for a, b in tiles]

    def backtrack(current_grid, remaining_tiles_mask):
        # Find the first empty cell
        r, c = -1, -1
        for i in range(H):
            for j in range(W):
                if current_grid[i][j] == 0:
                    r, c = i, j
                    break
            if r != -1:
                break

        # If all cells are filled, we have a valid placement
        if r == -1:
            return True

        # Try placing each available tile at (r, c)
        for i in range(N):
            if (remaining_tiles_mask >> i) & 1:
                a, b = tiles[i]

                # Try placing the tile in its original orientation
                for dr, dc in [(a, b), (b, a)]:
                    if r + dr <= H and c + dc <= W:
                        can_place = True
                        for row in range(r, r + dr):
                            for col in range(c, c + dc):
                                if current_grid[row][col] == 1:
                                    can_place = False
                                    break
                            if not can_place:
                                break

                        if can_place:
                            # Place the tile
                            for row in range(r, r + dr):
                                for col in range(c, c + dc):
                                    current_grid[row][col] = 1

                            # Recurse
                            if backtrack(current_grid, remaining_tiles_mask ^ (1 << i)):
                                return True

                            # Backtrack: remove the tile
                            for row in range(r, r + dr):
                                for col in range(c, c + dc):
                                    current_grid[row][col] = 0
                # If the tile is a square, rotating it doesn't create a new orientation
                if a == b:
                    continue

        return False

    # Optimization: Check if the total area of any subset of tiles can match the grid area.
    # This is a subset sum problem. Since N is small, we can iterate through all subsets.
    for i in range(1 << N):
        current_total_area = 0
        for j in range(N):
            if (i >> j) & 1:
                current_total_area += tile_areas[j]
        if current_total_area == grid_area:
            # Now, try to place the tiles from this subset
            initial_grid = [[0 for _ in range(W)] for _ in range(H)]
            if backtrack(initial_grid, i):
                print("Yes")
                return

    print("No")


