    # Additionally, the leftmost non-empty cell in row i must be R[i]
    # And the topmost non-empty cell in column j must be C[j]

    def is_valid_placement(grid, row_constraints, col_constraints):
        # Check row constraints: each row has exactly one A, B, C
        for i in range(N):
            row = grid[i]
            if row.count('A') != 1 or row.count('B') != 1 or row.count('C') != 1:
                return False

        # Check column constraints: each column has exactly one A, B, C
        for j in range(N):
            col = [grid[i][j] for i in range(N)]
            if col.count('A') != 1 or col.count('B') != 1 or col.count('C') != 1:
                return False

        # Check leftmost character in each row
        for i in range(N):
            for j in range(N):
                if grid[i][j] != '.':
                    if grid[i][j] != row_constraints[i]:
                        return False
                    break

        # Check topmost character in each column
        for j in range(N):
            for i in range(N):
                if grid[i][j] != '.':
                    if grid[i][j] != col_constraints[j]:
                        return False
                    break

        return True

    # Try all possible placements using backtracking
    def backtrack(grid, row, col):
        if row == N:
            if is_valid_placement(grid, R, C):
                return [row[:] for row in grid]
            return None

        if col == N:
            return backtrack(grid, row + 1, 0)

        # Try leaving this cell empty
        grid[row][col] = '.'
        result = backtrack(grid, row, col + 1)
        if result:
            return result

        # Try placing A, B, or C if it doesn't violate constraints
        for char in 'ABC':
            # Check if we can place this character
            grid[row][col] = char

            # Count of char in current row
            row_count = sum(1 for c in grid[row][:col+1] if c == char)
            if row_count > 1:  # Already have this char in row
                continue

            # Count of char in current column
            col_count = sum(1 for r in range(row) if grid[r][col] == char)
            if col_count >= 1:  # Already have this char in column above
                continue

            # If this is the first non-empty cell in the row, check leftmost constraint
            if all(grid[row][k] == '.' for k in range(col)) and char != R[row]:
                continue

            # If this is the first non-empty cell in the column, check topmost constraint
            if all(grid[k][col] == '.' for k in range(row)) and char != C[col]:
                continue

            result = backtrack(grid, row, col + 1)
            if result:
                return result

        # Reset cell
        grid[row][col] = '.'
        return None

    # Initialize empty grid
    grid = [['.' for _ in range(N)] for _ in range(N)]

    # Start backtracking
    result = backtrack(grid, 0, 0)

    if result:
        print("Yes")
        for row in result:
